{"files":[{"path":"solution/SensorStream.cs","content":"using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using FunnySharp;

public static class SensorStream
{
    public static async Task<TemperatureReport> ProcessAsync(
        IAsyncEnumerable<SensorReading> source,
        ReferenceService reference,
        CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(source);
        ArgumentNullException.ThrowIfNull(reference);
        cancellationToken.ThrowIfCancellationRequested();

        var temperatures = new List<TemperatureValue>();
        var runningMaxima = new List<double>();

        var converted = source.Choose(reading =>
            string.Equals(reading.Kind, "temperature", StringComparison.Ordinal)
                ? Option.Some(new TemperatureValue(
                    reading.SensorId,
                    Math.Round((reading.Value - 32) * 5 / 9, 2)))
                : Option.None<TemperatureValue>());

        await foreach (var temperature in converted
            .WithCancellation(cancellationToken)
            .ConfigureAwait(false))
        {
            temperatures.Add(temperature);
            runningMaxima.Add(runningMaxima.Count == 0
                ? temperature.Celsius
                : Math.Max(runningMaxima[runningMaxima.Count - 1], temperature.Celsius));
        }

        // Enumeration and source disposal finish before validation starts.
        cancellationToken.ThrowIfCancellationRequested();
        var checks = new List<Validation<double, string>>(temperatures.Count);

        foreach (var temperature in temperatures)
        {
            cancellationToken.ThrowIfCancellationRequested();
            var plausible = await reference
                .IsPlausibleAsync(temperature.Celsius, cancellationToken)
                .ConfigureAwait(false);

            checks.Add(plausible
                ? Validation<double, string>.Valid(temperature.Celsius)
                : Validation<double, string>.Invalid($"implausible:{temperature.SensorId}"));
        }

        // Validation sequencing accumulates every error in input order.
        var validated = checks.Sequence();
        cancellationToken.ThrowIfCancellationRequested();

        var temperatureSnapshot = temperatures.AsReadOnly();
        var maximaSnapshot = runningMaxima.AsReadOnly();
        return validated.Match(
            values => new TemperatureReport(
                temperatureSnapshot, maximaSnapshot, values, Array.Empty<string>()),
            errors => new TemperatureReport(
                temperatureSnapshot, maximaSnapshot, Array.Empty<double>(), errors));
    }
}
"}]}

